/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-table-scroll {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
}

:where([data-moru-registry]) .ui-table-scroll {
  width: 100%;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
}
:where([data-moru-registry]) .ui-table {
  width: 100%;
  border-collapse: collapse;
  caption-side: bottom;
  color: inherit;
  font: inherit;
  text-align: start;
}
:where([data-moru-registry]) .ui-table-head,
:where([data-moru-registry]) .ui-table-cell {
  height: max(40px, calc(var(--ui-control-height-md, 40px) + var(--ui-space, 4px)));
  padding: calc(var(--ui-space, 4px) * 2)
    calc(var(--ui-control-padding-x-md, 12px) + var(--ui-space, 4px));
  border-bottom: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  vertical-align: middle;
  text-align: start;
}
:where([data-moru-registry]) .ui-table-head {
  color: var(--ui-muted, #6e6e6b);
  background: var(--ui-surface, #fff);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-label-line-height, 1.45);
}
:where([data-moru-registry]) .ui-table-cell {
  font-size: var(--ui-type-body-size, 14px);
}
:where([data-moru-registry]) .ui-table-body .ui-table-row:last-child .ui-table-cell {
  border-bottom: 0;
}
:where([data-moru-registry]) .ui-table-body .ui-table-row:hover,
:where([data-moru-registry]) .ui-table-row[data-state='selected'] {
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-table-footer {
  background: var(--ui-control-hover-bg, #f3f3f1);
  font-weight: var(--ui-type-label-weight, 550);
}
:where([data-moru-registry]) .ui-table-caption {
  padding: calc(var(--ui-space, 4px) * 3);
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-caption-line-height, 1.5);
  text-align: start;
  overflow-wrap: anywhere;
}

:where([data-moru-registry]) .ui-table-scroll:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: 2px;
}
:where([data-moru-registry]) .ui-table-scroll:focus-visible {
  outline-offset: -3px;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { forwardRef, type ComponentPropsWithoutRef } from 'react'
import { cn } from './_lib/cn'
import './advanced-controls-shared.css'
import './table.css'

export type TableProps = ComponentPropsWithoutRef<'table'> & {
  scrollLabel?: string
  wrapperClassName?: string
}

/** The focusable wrapper scrolls; refs and native table attributes stay on the table. */
export const Table = forwardRef<HTMLTableElement, TableProps>(function Table(
  { className, wrapperClassName, scrollLabel: scrollLabelProp, ...props },
  ref,
) {
  const { t } = useI18n()
  const scrollLabel = scrollLabelProp ?? t('가로로 스크롤할 수 있는 데이터 표')

  return (
    <div
      className={cn('ui-table-scroll', wrapperClassName)}
      tabIndex={0}
      role="region"
      aria-label={scrollLabel}
    >
      <table {...props} ref={ref} className={cn('ui-table', className)} />
    </div>
  )
})

export const TableHeader = forwardRef<HTMLTableSectionElement, ComponentPropsWithoutRef<'thead'>>(
  function TableHeader({ className, ...props }, ref) {
    return <thead {...props} ref={ref} className={cn('ui-table-header', className)} />
  },
)
export const TableBody = forwardRef<HTMLTableSectionElement, ComponentPropsWithoutRef<'tbody'>>(
  function TableBody({ className, ...props }, ref) {
    return <tbody {...props} ref={ref} className={cn('ui-table-body', className)} />
  },
)
export const TableFooter = forwardRef<HTMLTableSectionElement, ComponentPropsWithoutRef<'tfoot'>>(
  function TableFooter({ className, ...props }, ref) {
    return <tfoot {...props} ref={ref} className={cn('ui-table-footer', className)} />
  },
)
export const TableRow = forwardRef<HTMLTableRowElement, ComponentPropsWithoutRef<'tr'>>(
  function TableRow({ className, ...props }, ref) {
    return <tr {...props} ref={ref} className={cn('ui-table-row', className)} />
  },
)
export const TableHead = forwardRef<HTMLTableCellElement, ComponentPropsWithoutRef<'th'>>(
  function TableHead({ className, scope = 'col', ...props }, ref) {
    return <th {...props} scope={scope} ref={ref} className={cn('ui-table-head', className)} />
  },
)
export const TableCell = forwardRef<HTMLTableCellElement, ComponentPropsWithoutRef<'td'>>(
  function TableCell({ className, ...props }, ref) {
    return <td {...props} ref={ref} className={cn('ui-table-cell', className)} />
  },
)
export const TableCaption = forwardRef<
  HTMLTableCaptionElement,
  ComponentPropsWithoutRef<'caption'>
>(function TableCaption({ className, ...props }, ref) {
  return <caption {...props} ref={ref} className={cn('ui-table-caption', className)} />
})
